-- Recovery database only. All fixtures roll back, including billing and session metadata.
begin;
do $$
declare u uuid; other_user uuid; session_id uuid; browser_id uuid:=gen_random_uuid(); lead_one uuid; lead_two uuid;
 account_sid text:='AC'||repeat('a',32); first_sid text:='CA'||replace(gen_random_uuid()::text,'-',''); second_sid text:='CA'||replace(gen_random_uuid()::text,'-','');
 destination text:='+12025550123'; caller text:='+12025550124'; result jsonb; first_call jsonb; listed jsonb; original_seen timestamptz;
begin
 select p.id,s.id into u,session_id from public.profiles p join auth.sessions s on s.user_id=p.id where p.active and not p.archived and p.role in ('agent','admin') limit 1;
 select id into other_user from public.profiles where id<>u and active and not archived limit 1;
 if u is null or other_user is null then raise exception 'Missing recovery test accounts with sessions';end if;
 insert into public.dialer_accounts(user_id,livemode,customer_id,subscription_status,paid_invoice,period_start,period_end,verified_at)
 values(u,true,'cus_incoming'||replace(gen_random_uuid()::text,'-',''),'active',true,now()-interval '1 day',now()+interval '29 days',now())
 on conflict(user_id,livemode) do update set subscription_status='active',paid_invoice=true,period_start=excluded.period_start,period_end=excluded.period_end,verified_at=now();
 insert into public.dialer_periods(user_id,livemode,starts_at,ends_at,subscription_id,customer_id) select user_id,livemode,period_start,period_end,coalesce(subscription_id,'sub_callbacktest'),customer_id from public.dialer_accounts where user_id=u and livemode on conflict(user_id,livemode,starts_at) do nothing;
 insert into public.dialer_numbers(user_id,livemode,slot,phone,state) values(u,true,3,destination,'active')
 on conflict(user_id,livemode,slot) do update set phone=excluded.phone,state='active';
 delete from public.dialer_callbacks where user_id=u;
 delete from public.dialer_incoming_presence where user_id=u;
 update public.dialer_calls set finished=true where user_id=u;
 insert into public.leads(division,status,assigned_to,phone,first_name) select division,'assigned',u,'(202) 555-0124','Match one' from public.profiles where id=u returning id into lead_one;
 insert into public.leads(division,status,assigned_to,phone,first_name) select division,'assigned',u,caller,'Match two' from public.profiles where id=u returning id into lead_two;
 insert into public.leads(division,status,assigned_to,phone,first_name) select division,'assigned',other_user,caller,'Not this agent' from public.profiles where id=other_user;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
 result:=public.dialer_callback_presence(u,true,session_id,browser_id,true,false);
 first_call:=public.dialer_callback_start(u,true,account_sid,first_sid,caller,destination);
 if first_call->>'identity' is distinct from result->>'identity' then raise exception 'Online agent did not ring';end if;
 begin perform public.dialer_create_call_with_incoming_guard(u,true,session_id,gen_random_uuid(),3,lead_one,null);raise exception 'TEST Outgoing call bypassed ringing callback';
 exception when raise_exception then if sqlerrm<>'Finish the incoming call before starting another call.' then raise;end if;end;
 result:=public.dialer_callback_start(u,true,account_sid,first_sid,caller,destination);
 if result<>first_call then raise exception 'Webhook retry changed callback';end if;
 result:=public.dialer_callback_start(u,true,account_sid,second_sid,caller,destination);
 if result->>'identity' is not null then raise exception 'Two callbacks rang simultaneously';end if;
 listed:=public.dialer_callback_list(u,true,0,(first_call->>'id')::uuid);
 if jsonb_array_length(listed->'calls')<>1 or jsonb_array_length(listed->'calls'->0->'matches')<>2 then raise exception 'Matching or owner isolation failed';end if;
 if jsonb_array_length(public.dialer_callback_list(other_user,true,0,(first_call->>'id')::uuid)->'calls')<>0 then raise exception 'Other account read callback';end if;
 perform public.dialer_callback_event(account_sid,first_sid,'answered',0);
 perform public.dialer_callback_event(account_sid,first_sid,'completed',42);
 perform public.dialer_callback_event(account_sid,first_sid,'missed',0);
 if not exists(select 1 from public.dialer_callbacks where parent_sid=first_sid and status='answered' and duration_seconds=42 and completed_at is not null) then raise exception 'Out-of-order event lost answered status';end if;
 perform public.dialer_callback_presence(u,true,session_id,browser_id,true,true);
 result:=public.dialer_callback_start(u,true,account_sid,'CA'||replace(gen_random_uuid()::text,'-',''),caller,destination);
 if result->>'identity' is not null then raise exception 'Busy agent rang';end if;
 perform public.dialer_callback_presence(u,true,session_id,browser_id,false,false);
 result:=public.dialer_callback_start(u,true,account_sid,'CA'||replace(gen_random_uuid()::text,'-',''),caller,destination);
 if result->>'identity' is not null then raise exception 'Offline agent rang';end if;
 result:=public.dialer_create_call_with_incoming_guard(u,true,session_id,gen_random_uuid(),3,lead_one,null);
 if result->>'to'<>caller then raise exception 'Existing outgoing lead grant changed';end if;
 update public.dialer_calls set finished=true where user_id=u;
 result:=public.dialer_create_call_with_incoming_guard(u,true,session_id,gen_random_uuid(),3,null,caller);
 if result->>'to'<>caller then raise exception 'Existing manual call grant changed';end if;
 begin perform public.dialer_callback_presence(u,true,gen_random_uuid(),browser_id,true,false);raise exception 'TEST Invalid session registered';
 exception when raise_exception then if sqlerrm like 'TEST%' then raise;end if;end;
 execute 'reset role';
 update public.leads set assigned_to=null,status='unassigned' where id=lead_one;
 execute 'set local role service_role';listed:=public.dialer_callback_list(u,true,0,(first_call->>'id')::uuid);
 if jsonb_array_length(listed->'calls'->0->'matches')<>1 then raise exception 'Transferred lead leaked';end if;
 execute 'reset role';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated','aal','aal2')::text,true);execute 'set local role authenticated';
 if public.my_dialer_callback_unread()<1 then raise exception 'Missing callback notification';end if;
 begin perform public.dialer_callback_list(u,true);raise exception 'TEST Client accessed service RPC';exception when insufficient_privilege then null;end;
 begin perform 1 from public.dialer_callbacks;raise exception 'TEST Client read raw callback table';exception when insufficient_privilege then null;end;
 execute 'reset role';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated','aal','aal1')::text,true);execute 'set local role authenticated';
 begin perform public.my_dialer_callback_unread();raise exception 'TEST AAL1 read notifications';exception when insufficient_privilege then null;end;
 execute 'reset role';execute 'set local role anon';
 begin perform public.my_dialer_callback_unread();raise exception 'TEST Anonymous notifications';exception when insufficient_privilege then null;end;
 execute 'reset role';
 if (select public from storage.buckets where id='dialer-voicemails') then raise exception 'Voicemail bucket is public';end if;
end $$;
select 'PASS: online ringing, simultaneous call protection, busy/offline voicemail, replay safety, matching lead isolation, ordered status, session and MFA checks, private bucket' result;
rollback;
